command:
$ErrorActionPreference="Stop"
$main="09851775bf18340ccaf471313c380b474a17b7f6"
$candidate="029ef1e5d8f186bfc5262d386576204b58fa47a9"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$worktree=Join-Path $env:RUNNER_TEMP "fly-indexed-date-029ef1e5"
Set-Location -LiteralPath $repo
if(Test-Path -LiteralPath $worktree){throw "Candidate worktree exists"}
& git fetch origin main feat/search-v3-indexed-modified-date --no-tags
if($LASTEXITCODE -ne 0){throw "Candidate fetch failed"}
$originMain=(& git rev-parse refs/remotes/origin/main).Trim()
if($originMain -ne $main){throw "Main SHA drift"}
$originFeature=(& git rev-parse refs/remotes/origin/feat/search-v3-indexed-modified-date).Trim()
if($originFeature -ne $candidate){throw "Candidate SHA drift"}
try {
 & git worktree add --detach $worktree $candidate
 if($LASTEXITCODE -ne 0){throw "Owned worktree add failed"}
 Set-Location -LiteralPath $worktree
 & python -X utf8 -m py_compile tests/winui/test_indexed_search_contract.py tests/winui/test_indexed_search_native.py tests/winui/test_indexed_search_gui.py tests/winui/m19/test_native.py
 if($LASTEXITCODE -ne 0){throw "INDEXED_DATE_SYNTAX_FAIL"}
 & python -X utf8 -m unittest tests/winui/test_indexed_search_contract.py
 if($LASTEXITCODE -ne 0){throw "INDEXED_DATE_CONTRACT_FAIL"}
 Write-Host "INDEXED_DATE_SOURCE=PASS"
 & cmd.exe /c tests\winui\m19\build.cmd Release
 if($LASTEXITCODE -ne 0){throw "INDEXED_DATE_NATIVE_BUILD_FAIL"}
 $env:FLY_M19_CONFIG="Release"
 & python -X utf8 tests/winui/m19/test_native.py
 if($LASTEXITCODE -ne 0){throw "INDEXED_DATE_NATIVE_FAIL"}
 Write-Host "INDEXED_DATE_NATIVE=PASS"
 & cmd.exe /c build.bat Release
 if($LASTEXITCODE -ne 0){throw "INDEXED_DATE_PRODUCT_BUILD_FAIL"}
 Write-Host "INDEXED_DATE_PRODUCT_BUILD=PASS"
 & python -X utf8 tests/winui/test_indexed_search_native.py --configuration Release
 if($LASTEXITCODE -ne 0){throw "INDEXED_DATE_SYSTEMINDEX_FAIL"}
 Write-Host "INDEXED_DATE_SYSTEMINDEX=PASS"
 & python -X utf8 tests/winui/test_indexed_search_gui.py --configuration Release --capture after
 if($LASTEXITCODE -ne 0){throw "INDEXED_DATE_GUI_FAIL"}
 Write-Host "INDEXED_DATE_GUI=PASS"
 & git diff --check
 if($LASTEXITCODE -ne 0){throw "INDEXED_DATE_DIFF_CHECK_FAIL"}
 Write-Host "INDEXED_DATE_FOCUSED_ACCEPTANCE=PASS"
} finally {
 Remove-Item Env:FLY_M19_CONFIG -ErrorAction SilentlyContinue
 Set-Location -LiteralPath $repo
 if(Test-Path -LiteralPath $worktree){& git worktree remove --force $worktree}
 & git worktree prune
}
